fn find_page(plan: &Plan, page: &str) -> Result<usize> {
    plan.order
        .iter()
        .position(|p| p == page)
        .ok_or_else(|| Error::Invalid(format!("page `{page}` is no longer in the plan")))
}

/// Check and apply the answer to a pending task. Returns warnings; a rejected answer is an
/// error listing what to fix, and the task stays pending. Each submit is recorded in the
/// run log, with the coverage of a planning answer's quotes.
pub fn submit(project: &Project, id: &str) -> Result<Vec<String>> {
    use crate::runlog::{Outcome, What};
    let _lock = Lock::acquire(project)?;
    let task = load_state(project)?
        .pending
        .into_iter()
        .find(|t| t.id == id);
    let coverage = task.as_ref().and_then(|t| planning_coverage(project, t));
    let events = crate::runlog::load(project);
    // With `[checks] coverage = "reject"`, an answer drawn from part of the sources goes
    // back, at most `coverage_retries` times; after that it is accepted with a warning.
    // A pilot's argument explains part of the target, so it may leave sections unquoted.
    let pilot_argument = matches!(task.as_ref().map(|t| &t.kind), Some(Kind::Argument))
        && project.load_graph()?.is_some_and(|g| g.pilot.is_some());
    let shortfall = coverage
        .as_deref()
        .filter(|_| !pilot_argument)
        .and_then(|c| {
            let results =
                project.config.checks.coverage_depth == crate::config::CoverageDepth::Results;
            crate::coverage::rejection(c, &project.sources, results)
        });
    let rejecting = project.config.checks.coverage == crate::config::CoverageCheck::Reject;
    let sent_back = crate::runlog::coverage_rejections(&events, id);
    let gate = shortfall
        .clone()
        .filter(|_| rejecting && sent_back < project.config.checks.coverage_retries as usize);
    let result = submit_locked(project, id, gate.as_deref()).map(|mut warnings| {
        if rejecting && gate.is_none() && shortfall.is_some() {
            warnings.push(format!(
                "accepted after {sent_back} rejections for coverage, with most of the sections \
                 that develop results still unquoted (see `exegenius status`)"
            ));
        }
        warnings
    });
    let check = match (&result, &gate) {
        (Err(Error::Invalid(m)), Some(g)) if m == g => Some("coverage".to_string()),
        _ => None,
    };
    let (outcome, message, warnings) = match &result {
        Ok(warnings) => (Outcome::Accepted, None, warnings.clone()),
        // Checked and rejected, as opposed to not checked: no answer file, or not pending.
        Err(e @ Error::Invalid(m)) if task.is_some() && !m.starts_with("no answer yet") => {
            (Outcome::Rejected, Some(e.to_string()), Vec::new())
        }
        Err(e) => (Outcome::Error, Some(e.to_string()), Vec::new()),
    };
    let attempt = crate::runlog::submits(&events, id) + 1;
    crate::runlog::append(
        project,
        What::Submit {
            task: id.to_string(),
            kind: task.as_ref().map(|t| t.label().to_string()),
            attempt,
            outcome,
            message,
            warnings,
            check,
            coverage,
        },
    );
    result
}

/// For an extract or argument task whose answer file parses: where the answer's quotes
/// fall in the sources.
fn planning_coverage(project: &Project, task: &Task) -> Option<Vec<crate::coverage::Coverage>> {
    use crate::coverage::{argument_owners, concept_owners, coverage};
    let text = std::fs::read_to_string(project.root.join(task.answer())).ok()?;
    match task.kind {
        Kind::Extract => {
            let answer: ExtractAnswer = serde_json::from_str(&text).ok()?;
            Some(coverage(
                &project.sources,
                &concept_owners(&answer.concepts),
            ))
        }
        Kind::Argument => {
            let answer: ArgumentAnswer = serde_json::from_str(&text).ok()?;
            let graph = project.load_graph().ok().flatten();
            Some(coverage(
                &project.sources,
                &argument_owners(&answer.root, graph.as_ref()),
            ))
        }
        _ => None,
    }
}

/// [`submit`], under the lock. `gate` is the rejection to give an extract or argument answer
/// that passes its other checks.
fn submit_locked(project: &Project, id: &str, gate: Option<&str>) -> Result<Vec<String>> {
    let mut state = load_state(project)?;
    let Some(index) = state.pending.iter().position(|t| t.id == id) else {
        return Err(Error::Invalid(format!(
            "`{id}` is not a pending task (run `exegenius next` to see the pending tasks)"
        )));
    };
    let task = state.pending[index].clone();
    let path = project.root.join(task.answer());
    if !path.exists() {
        return Err(Error::Invalid(format!(
            "no answer yet: write it to {}",
            task.answer().display()
        )));
    }
    let text = read(&path)?;
    let graph = project.load_graph()?;
    let warnings = match &task.kind {
        Kind::Extract => {
            let (graph, warnings) = apply_extract(project, parse(&path, &text)?)?;
            if let Some(gate) = gate {
                return Err(Error::Invalid(gate.to_string()));
            }
            project.save_graph(&graph)?;
            warnings
        }
        Kind::Background => {
            let mut graph = require(graph)?;
            apply_background(&mut graph, parse(&path, &text)?)?;
            project.save_graph(&graph)?;
            Vec::new()
        }
        Kind::Extend => {
            let mut graph = require(graph)?;
            let limit = crate::extract::new_pages(&crate::audit::load_rounds(project)?);
            let warnings = apply_extend(project, &mut graph, parse(&path, &text)?, limit)?;
            project.save_graph(&graph)?;
            warnings
        }
        Kind::Argument => {
            let graph = require(graph)?;
            let plan = plan(&graph, &project.sources)?;
            let answer: ArgumentAnswer = parse(&path, &text)?;
            if let Some(gate) = gate {
                crate::argument::validate(project, &graph, &plan, &answer)?;
                return Err(Error::Invalid(gate.to_string()));
            }
            apply_argument(project, &graph, &plan, answer)?
        }
        Kind::Write { page } => {
            let mut graph = require(graph)?;
            let plan = plan(&graph, &project.sources)?;
            find_page(&plan, page)?;
            let fields_path = project
                .root
                .join(task.fields().expect("write tasks have a fields file"));
            if !fields_path.exists() {
                return Err(Error::Invalid(format!(
                    "no answer yet: write the symbols the page binds to {} (an empty list if \
                     it binds none)",
                    task.fields()
                        .expect("write tasks have a fields file")
                        .display()
                )));
            }
            let fields = parse(&fields_path, &read(&fields_path)?)?;
            let warnings = apply_write(project, &mut graph, &plan, page, &text, fields)?;
            project.save_graph(&graph)?;
            warnings
        }
        Kind::Audit { page, input } => {
            let mut graph = require(graph)?;
            let plan = plan(&graph, &project.sources)?;
            let i = find_page(&plan, page)?;
            let body = project.page_body(page)?.unwrap_or_default();
            let levels = crate::audit::levels(crate::argument::load(project)?.as_ref(), page);
            let audit = apply_audit(&mut graph, &plan, i, &body, parse(&path, &text)?, levels)?;
            state.round_gaps += audit.gaps.len();
            state.audited.insert(page.clone(), input.clone());
            record(project, state.round, audit)?;
            project.save_graph(&graph)?;

//! Where a planning answer's quotes fall in the sources: a diagnostic recorded for every
//! extract and argument answer, and, with `[checks] coverage = "reject"`, a reason to send
//! an answer back ([`Coverage::shortfall`], [`rejection`]).
//!
//! The extract and argument tasks quote the sources as evidence. Submit checks that each
//! quote is in its source, and nothing else about where the quotes come from, so a plan
//! drawn from the introduction alone passes (2026-10-13-planner-handoff-run). This module
//! measures, for each source:
//!
//! - how far into the source the quotes reach, in lines, and how many fall in its first
//!   tenth;
//! - which sections hold a quote, and which theorem-like statements (lemmas, theorems,
//!   definitions) lie in a section that holds none;
//! - which concepts or pages share their name with a section heading but quote none of the
//!   sections so named.
//!
//! What it cannot establish: that the plan covers the proof. A quote shows that a passage
//! was read and cited, not that the step it supports is in the plan, and a plan can quote
//! every section and still miss a derivation. A section with no quote may not matter to the
//! target, and a result argued in prose, outside any theorem-like environment, counts in no
//! statement figure. A short quote that occurs more than once is placed at its first occurrence,
//! which can be the introduction's summary rather than the passage the agent read; such
//! quotes are counted as `repeated`. Heading matches compare words without stemming
//! ("butterfly" does not match "butterflies"). Judging coverage of the proof needs a
//! reference of what the plan must contain, which this module does not have.

use std::collections::BTreeSet;

use serde::{Deserialize, Serialize};

use crate::argument::Node;
use crate::graph::{Concept, Evidence, Graph};
use crate::project::{Heading, Source};
use crate::text::key;

/// A part of a planning answer that quotes the sources: a concept, or a step of the
/// argument.
#[derive(Debug, Clone)]
pub struct Owner<'a> {
    /// The concept's id, or the step's id.
    pub id: String,
    /// Names to look for in section headings: the concept's name and aliases, or the name
    /// and aliases of the page that presents the step.
    pub terms: Vec<String>,
    pub quotes: Vec<&'a Evidence>,
}

/// Where the quotes of one planning answer fall in one source.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Coverage {
    pub source: String,
    /// Lines in the source, blank ones included.
    pub lines: usize,
    /// Quotes naming this source.
    pub quotes: usize,
    /// Quotes found in the source word for word.
    pub located: usize,
    /// Located quotes that occur more than once in the source: each is placed at its first
    /// occurrence.
    pub repeated: usize,
    /// The first and last lines a located quote starts on.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub span: Option<(usize, usize)>,
    /// Located quotes starting in the first tenth of the source's lines.
    pub first_tenth: usize,
    /// Whether the source's sections are marked up (LaTeX or markdown). For a source
    /// whose sections are not, `sections`, `unquoted_statements`, `statements` and
    /// `elsewhere` are left empty: headings guessed from numbered lines are unreliable.
    pub structured: bool,
    /// Every section, with the text before the first heading as "(front matter)".
    pub sections: Vec<SectionCoverage>,
    /// Theorem-like statements in a section that holds no quote, as "Lemma `lem:x` (line
    /// 1234)".
    pub unquoted_statements: Vec<String>,
    /// Theorem-like statements in the source.
    pub statements: usize,
    /// Concepts or pages named in a section heading whose quotes lie in none of the sections
    /// so named.
    pub elsewhere: Vec<Elsewhere>,
    /// The results the source states: its theorem-like statements and its labelled displayed
    /// equations. Each runs to the next result or heading.
    #[serde(default)]
    pub results: usize,
    /// The results whose stretch of the source holds a quote.
    #[serde(default)]
    pub quoted_results: usize,
    /// The results whose stretch holds no quote, in order.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub unquoted_results: Vec<ResultRef>,
}

/// A result of a source: a theorem-like statement or a labelled displayed equation.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ResultRef {
    /// The top-level section it is in.
    pub section: String,
    /// What it is: "Lemma `lem:x`" or "equation `eq:y`".
    pub what: String,
    pub line: usize,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SectionCoverage {
    pub title: String,
    /// 1 for a section, 2 for a subsection; the front matter counts as a section.
    pub level: usize,
    /// First and last line of the section, its subsections included.
    pub lines: (usize, usize),
    /// Located quotes in the section, its subsections included.
    pub quotes: usize,
    /// Theorem-like statements in the section, its subsections included.
    pub statements: usize,
    /// Displayed equations in the section, its subsections included.
    #[serde(default)]
    pub displays: usize,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Elsewhere {
    /// The concept's or step's id.
    pub id: String,
    /// The name found in the headings.
    pub term: String,
    /// The sections whose headings name it.
    pub headings: Vec<String>,
    /// The sections its quotes lie in.
    pub quoted_in: Vec<String>,
}

/// A section's extent in the normalised text.
struct Span {
    title: String,
    level: usize,
    start: usize,
    end: usize,
}

/// Each heading's section runs to the next heading at the same level or above; the text
/// before the first heading is the front matter, at the top level.
fn spans(source: &Source) -> Vec<Span> {
    let headings = source.sections();
    let total = source.normalised.len();
    let top = headings.iter().map(|h| h.level).min().unwrap_or(1);
    let mut spans = Vec::new();
    let first = headings.first().map_or(total, |h| h.offset);
    if first > 0 {
        spans.push(Span {
            title: "(front matter)".into(),
            level: top,
            start: 0,
            end: first,
        });
    }
    for (i, h) in headings.iter().enumerate() {
        let end = headings[i + 1..]
            .iter()
            .find(|n| n.level <= h.level)
            .map_or(total, |n: &Heading| n.offset);
        spans.push(Span {
            title: h.title.clone(),
            level: h.level,
            start: h.offset,
            end,
        });
    }
    spans
}

/// The words of a name or heading, lowercased, for matching a name inside a heading.
fn words(s: &str) -> Vec<String> {
    key(s)
        .split(|c: char| !c.is_alphanumeric())
        .filter(|w| !w.is_empty())
        .map(str::to_string)
        .collect()
}

fn names(heading: &[String], term: &[String]) -> bool {
    !term.is_empty() && heading.windows(term.len()).any(|w| w == term)
}

/// Where the owners' quotes fall in each source. Quotes naming no source are left out.
pub fn coverage(sources: &[Source], owners: &[Owner]) -> Vec<Coverage> {
    sources
        .iter()
        .map(|source| of_source(source, owners))
        .collect()
}

fn of_source(source: &Source, owners: &[Owner]) -> Coverage {
    let structured = source.marked_up();
    let spans = if structured {
        spans(source)
    } else {
        Vec::new()
    };
    let innermost = |at: usize| {
        spans
            .iter()
            .filter(|s| s.start <= at && at < s.end.max(s.start + 1))
            .max_by_key(|s| s.level)
    };
    let tenth = source.line_count().div_ceil(10);
    let mut quotes = 0;
    let mut repeated = 0;
    let mut located = Vec::new();
    // For each owner, the offsets of its located quotes.
    let mut placed: Vec<Vec<usize>> = Vec::new();
    for owner in owners {
        let mut at = Vec::new();
        for q in owner.quotes.iter().filter(|q| q.source == source.id) {
            quotes += 1;
            let found = source.occurrences(&q.quote);
            if found.len() > 1 {
                repeated += 1;
            }
            if let Some(&first) = found.first() {
                located.push(first);
                at.push(first);
            }
        }
        placed.push(at);
    }
    let lines: Vec<usize> = located.iter().map(|&o| source.line_at(o)).collect();
    let span = lines
        .iter()
        .min()
        .zip(lines.iter().max())
        .map(|(&a, &b)| (a, b));
    let first_tenth = lines.iter().filter(|&&l| l <= tenth).count();
    let last_line = |end: usize| {
        if end >= source.normalised.len() {
            source.line_count()
        } else {
            source.line_at(end).saturating_sub(1).max(1)
        }
    };
    let statements = if structured { source.statements() } else { &[] };
    let sections: Vec<SectionCoverage> = spans
        .iter()
        .map(|s| SectionCoverage {
            title: s.title.clone(),
            level: s.level,
            lines: (source.line_at(s.start), last_line(s.end)),
            quotes: located
                .iter()
                .filter(|&&o| s.start <= o && o < s.end)
                .count(),
            statements: statements
                .iter()
                .filter(|t| s.start <= t.offset && t.offset < s.end)
                .count(),
            displays: source
                .displays()
                .iter()
                .filter(|d| s.start <= d.offset && d.offset < s.end)
                .count(),
        })
        .collect();
    let quoted: BTreeSet<&str> = located
        .iter()
        .filter_map(|&o| innermost(o))
        .map(|s| s.title.as_str())
        .collect();
    let unquoted_statements = statements
        .iter()
        .filter(|t| innermost(t.offset).is_none_or(|s| !quoted.contains(s.title.as_str())))
        .map(|t| match &t.label {
            Some(label) if label.starts_with(&t.kind) => format!("{label} (line {})", t.line),
            Some(label) => format!("{} `{label}` (line {})", t.kind, t.line),
            None => format!("{} (line {})", t.kind, t.line),
        })
        .collect();
    let mut elsewhere = Vec::new();
    for (owner, at) in owners.iter().zip(&placed) {
        if at.is_empty() {
            continue;
        }
        for term in &owner.terms {
            let term_words = words(term);
            if term_words.concat().chars().count() < 4 {
                continue;
            }
            let named: Vec<&Span> = spans
                .iter()
                .filter(|s| s.title != "(front matter)" && names(&words(&s.title), &term_words))
                .collect();
            if named.is_empty() {
                continue;
            }
            let inside = at
                .iter()
                .any(|&o| named.iter().any(|s| s.start <= o && o < s.end));
            if !inside {
                let mut in_order = at.clone();
                in_order.sort_unstable();
                let mut quoted_in: Vec<String> = in_order
                    .into_iter()
                    .filter_map(innermost)
                    .map(|s| s.title.clone())
                    .collect();
                quoted_in.dedup();
                elsewhere.push(Elsewhere {
                    id: owner.id.clone(),
                    term: term.clone(),
                    headings: named.iter().map(|s| s.title.clone()).collect(),
                    quoted_in,
                });
            }
            // One heading match per owner is enough to report.
            break;
        }
    }
    // Results, each running to the next result or heading at any level.
    let mut results: Vec<(usize, usize, String)> = Vec::new();
    if structured {
        for t in source.statements() {
            let what = match &t.label {
                Some(label) => format!("{} `{label}`", t.kind),
                None => t.kind.clone(),
            };
            results.push((t.offset, t.line, what));
        }
        for d in source.displays() {
            if let Some(label) = &d.label {
                results.push((d.offset, d.line, format!("equation `{label}`")));
            }
        }
    }
    results.sort_by_key(|r| r.0);
    let mut bounds: Vec<usize> = results
        .iter()
        .map(|r| r.0)
        .chain(source.sections().iter().map(|h| h.offset))
        .collect();
    bounds.sort_unstable();
    let top = spans.iter().map(|s| s.level).min().unwrap_or(1);
    let mut unquoted_results = Vec::new();
    for (start, line, what) in &results {
        let end = bounds
            .iter()
            .find(|&&b| b > *start)
            .copied()
            .unwrap_or(source.normalised.len());
        if !located.iter().any(|&o| *start <= o && o < end) {
            let section = spans
                .iter()
                .filter(|s| s.level == top && s.start <= *start && *start < s.end)
                .map(|s| s.title.clone())
                .next()
                .unwrap_or_default();
            unquoted_results.push(ResultRef {
                section,
                what: what.clone(),
                line: *line,
            });
        }
    }
    Coverage {
        results: results.len(),
        quoted_results: results.len() - unquoted_results.len(),
        unquoted_results,
        source: source.id.clone(),
        lines: source.line_count(),
        quotes,
        located: located.len(),
        repeated,
        span,
        first_tenth,
        sections,
        unquoted_statements,
        structured,
        statements: statements.len(),
        elsewhere,
    }
}

/// The owners in a set of concepts: each concept's evidence, named by its name and aliases.
pub fn concept_owners(concepts: &[Concept]) -> Vec<Owner<'_>> {
    concepts
        .iter()
        .map(|c| Owner {
            id: c.id.clone(),
            terms: std::iter::once(&c.name)
                .chain(&c.aliases)
                .cloned()
                .collect(),
            quotes: c.evidence.iter().collect(),
        })
        .collect()
}

/// The owners in an argument: the root, and each other step a page presents, with the
/// quotes of the steps it presents itself (infer steps' quotes and explicit motivations'
/// quotes, down to steps another page presents), named by its page's name and aliases in
/// `graph`. Each quote belongs to one owner.
pub fn argument_owners<'a>(root: &'a Node, graph: Option<&Graph>) -> Vec<Owner<'a>> {
    let owner = |node: &Node| Owner {
        id: node.id.clone(),
        terms: node
            .page
            .as_deref()
            .and_then(|page| graph?.get(page))
            .map(|c| {
                std::iter::once(&c.name)
                    .chain(&c.aliases)
                    .cloned()
                    .collect()
            })
            .unwrap_or_default(),
        quotes: Vec::new(),
    };
    let mut owners = vec![owner(root)];
    // Depth first, each node with the index of the owner its quotes go to.
    let mut stack = vec![(root, 0)];
    while let Some((node, mut at)) = stack.pop() {
        if node.page.is_some() && !std::ptr::eq(node, root) {
            owners.push(owner(node));
            at = owners.len() - 1;
        }
        let quotes = node
            .quote
            .iter()
            .chain(node.motivation.as_ref().and_then(|m| m.quote.as_ref()));
        owners[at].quotes.extend(quotes);
        stack.extend(node.children.iter().rev().map(|c| (c, at)));
    }
    owners
}

/// Why an answer whose quotes leave most of a source's sections unquoted is sent back, or
/// None if no source has a [`Coverage::shortfall`]. With `results`, also when the quotes
/// reach too few of a source's results ([`Coverage::results_shortfall`]). The message names
/// where the quotes come from and what they leave unquoted, and asks for the source to be
/// read in full.
pub fn rejection(coverage: &[Coverage], sources: &[Source], results: bool) -> Option<String> {
    let mut parts = Vec::new();
    for c in coverage {
        let path = sources
            .iter()
            .find(|s| s.id == c.source)
            .map_or(c.source.clone(), |s| s.path.display().to_string());
        if let Some(unquoted) = c.shortfall() {
            let from = c
                .span
                .map_or("no lines".to_string(), |(a, b)| format!("lines {a}–{b}"));
            let sections = unquoted
                .iter()
                .map(|s| {
                    format!(
                        "- {} (lines {}–{}): {} theorem-like statements, {} displayed equations",
                        s.title, s.lines.0, s.lines.1, s.statements, s.displays
                    )
                })
                .collect::<Vec<_>>()
                .join("\n");
            parts.push(format!(
                "The quotes from `{path}` come from {from} of its {} lines, and none comes \
                 from these sections, which develop results in theorems, lemmas, definitions \
                 or displayed equations:\n{sections}",
                c.lines
            ));
        } else if let Some(unquoted) = c.results_shortfall().filter(|_| results) {
            let mut by_section: Vec<(String, Vec<String>)> = Vec::new();
            for r in unquoted {
                let item = format!("{} (line {})", r.what, r.line);
                match by_section.last_mut() {
                    Some((section, items)) if *section == r.section => items.push(item),
                    _ => by_section.push((r.section.clone(), vec![item])),
                }
            }
            let list = by_section
                .iter()
                .map(|(section, items)| format!("- {section}: {}", items.join(", ")))
                .collect::<Vec<_>>()
                .join("\n");
            parts.push(format!(
                "Of the {} results `{path}` states (its theorems, lemmas and definitions, and \
                 its labelled equations), the quotes fall where {} of them is stated or \
                 derived. These are not quoted:\n{list}",
                c.results, c.quoted_results
            ));
        }
    }
    if parts.is_empty() {
        return None;
    }
    let advice = if results {
        "An introduction summarises results, and a section's opening introduces them; the \
         results themselves, and their derivations, come after, and the target depends on \
         them. Read each source to its last line, in parts (the Read tool's offset and limit), \
         and revise the answer: keep what holds, add what the target depends on, and quote \
         each concept or step at the theorem, lemma or equation that states or derives it, \
         rather than where an introduction mentions it. A result the target does not depend \
         on may stay unquoted."
    } else {
        "An introduction summarises results; the sections after it develop them, and the \
         target depends on that development. Read each source to its last line, in parts (the \
         Read tool's offset and limit), and revise the answer: keep what holds, add what the \
         target depends on, and quote each concept or step where the sources develop it \
         rather than where the introduction mentions it. A section the target does not depend \
         on may stay unquoted."
    };
    Some(format!(
        "answer rejected: it is drawn from part of the sources.\n\n{}\n\n{advice}",
        parts.join("\n\n")
    ))
}

impl Coverage {
    /// The results with no quote, if fewer than a tenth of the source's results hold one:
    /// the mark of an answer that quotes sections' openings or summaries but not the results
    /// they state. None for a source whose sections are not marked up, or that states no
    /// results. The tenth is calibrated on the plans of the n log n paper
    /// (2026-10-13-depth-rejection): plans drawn from summaries quote at most 3 of its 66
    /// results, plans drawn from reading it at least 8.
    pub fn results_shortfall(&self) -> Option<&[ResultRef]> {
        (self.structured && self.results > 0 && self.quoted_results * 10 < self.results)
            .then_some(self.unquoted_results.as_slice())
    }

    }

    /// The top-level sections that develop mathematics (hold theorem-like statements or
    /// displayed equations) and no quote, if they are more than half of the top-level
    /// sections that develop mathematics: the mark of an answer drawn from part of a source.
    /// None for a source whose sections are not marked up.
    pub fn shortfall(&self) -> Option<Vec<&SectionCoverage>> {
        let top = self.sections.iter().map(|s| s.level).min()?;
        let holding: Vec<&SectionCoverage> = self
            .sections
            .iter()
            .filter(|s| {
                s.level == top && s.statements + s.displays > 0 && s.title != "(front matter)"
            })
            .collect();
        let unquoted: Vec<&SectionCoverage> =
            holding.iter().copied().filter(|s| s.quotes == 0).collect();
        (self.structured && unquoted.len() * 2 > holding.len()).then_some(unquoted)
    }

    /// Lines for `exegenius status`: the reach, the top-level sections quoted, statements in
    /// unquoted sections, and up to `names` concepts or steps quoted away from the sections
    /// their names head.
    pub fn summary(&self, names: usize) -> Vec<String> {
        let mut out = Vec::new();
        let span = self.span.map_or("none located".to_string(), |(a, b)| {
            format!("lines {a}–{b} of {}", self.lines)
        });
        out.push(format!(
            "{}: {} quotes, {} located ({} occur more than once and are placed at the first); \
             {span}; {} in the first tenth",
            self.source, self.quotes, self.located, self.repeated, self.first_tenth
        ));
        if !self.structured {
            out.push(
                "sections and theorem-like statements not reported: the source's headings are \
                 not marked up (LaTeX or markdown)"
                    .to_string(),
            );
            return out;
        }
        let top = self.sections.iter().map(|s| s.level).min().unwrap_or(1);
        let tops: Vec<&SectionCoverage> = self.sections.iter().filter(|s| s.level == top).collect();
        let with: Vec<String> = tops
            .iter()
            .filter(|s| s.quotes > 0)
            .map(|s| format!("{} ({})", s.title, s.quotes))
            .collect();
        if !tops.is_empty() {
            out.push(format!(
                "top-level sections with a quote: {} of {}{}",
                with.len(),
                tops.len(),
                if with.is_empty() {
                    String::new()
                } else {
                    format!(": {}", with.join(", "))
                }
            ));
        }
        if self.statements > 0 {
            out.push(format!(
                "theorem-like statements in sections with no quote: {} of {}",
                self.unquoted_statements.len(),
                self.statements
            ));
        }
        for e in self.elsewhere.iter().take(names) {
            out.push(format!(
                "`{}` is named in the heading of {} but quoted only in {}",
                e.id,
                e.headings.join("; "),
                e.quoted_in.join("; ")
            ));
        }
        if self.elsewhere.len() > names {
            out.push(format!(
                "and {} more named in a heading but quoted elsewhere",
                self.elsewhere.len() - names
            ));
        }
        out
    }
}

