def tokens(latex):
    out = []
    i = 0
    while i < len(latex):
        c = latex[i]
        if c == '\\':
            if i + 1 < len(latex) and latex[i + 1].isascii() and latex[i + 1].isalpha():
                j = i + 1
                while j < len(latex) and latex[j].isascii() and latex[j].isalpha():
                    j += 1
                tok = latex[i:j]
            elif i + 1 < len(latex):
                tok = latex[i:i + 2]
            else:
                tok = '\\'
        else:
            tok = c
        i += len(tok)
        if tok in ('\\,', '\\;', '\\:', '\\!', '\\ ', '~', '{', '}') or tok.isspace():
            continue
        out.append(tok)
    return out

def math(text):
    return re.findall(r'(?<!\$)\$(?!\$)(.+?)(?<!\$)\$(?!\$)', text)

def occurs(sym, maths):
    want = tokens(sym)
    for m in maths:
        t = tokens(m)
        for k in range(len(t) - len(want) + 1):
            if t[k:k + len(want)] == want:
                return True
    return False

